#!/usr/bin/env node
// Lists every Maven artifact in the Android release APK (the app's releaseRuntimeClasspath, transitive
// ones included) with the licence its POM declares, into scripts/licenses/android.json, which
// scripts/licenses.mjs turns into the Credits screen's Android section. Done here instead of a Gradle
// licence plugin: android/ is generated by prebuild (CNG) and the build stays as Expo makes it.
//
//   npx expo prebuild --platform android   (once)
//   node scripts/licenses/android-deps.mjs  then  node scripts/licenses.mjs
//
// POMs come from the Gradle cache the dependency resolution fills (~/.gradle/caches/modules-2); a POM
// without <licenses> inherits its <parent>'s. Re-run after a dependency or Expo SDK change.
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), '../..');
const outFile = path.join(root, 'scripts/licenses/android.json');
const cache = path.join(process.env.GRADLE_USER_HOME ?? path.join(os.homedir(), '.gradle'), 'caches/modules-2/files-2.1');
const JAVA_HOME = process.env.JAVA_HOME ?? '/Applications/Android Studio.app/Contents/jbr/Contents/Home';

const tree = execFileSync('./gradlew', [':app:dependencies', '--configuration', 'releaseRuntimeClasspath', '-q'], {
  cwd: path.join(root, 'android'),
  env: { ...process.env, JAVA_HOME },
  encoding: 'utf8',
  maxBuffer: 64 * 1024 * 1024,
});

// "+--- group:artifact:1.0 -> 1.2 (*)", "\--- group:artifact -> 1.2", or a substitution
// "group:artifact:+ -> other.group:other-artifact:1.2": what Gradle resolved.
// Expo modules come from each npm package's local-maven-repo (POMs without licences): the JS list
// credits those packages already.
const coords = new Map();
for (const line of tree.split('\n')) {
  const m = /^[|+\\ -]*[+\\]--- ([\w.-]+):([\w.-]+)(?::([^\s]+))?(?: -> ([^\s]+))?/.exec(line);
  if (!m || line.includes('--- project ')) continue;
  let [, group, artifact, version] = m;
  const resolved = m[4]?.split(':');
  if (resolved?.length === 3) [group, artifact, version] = resolved;
  else if (resolved?.length === 1) version = resolved[0];
  if (!version || /^[{[+]/.test(version) || group === 'host.exp.exponent' || group.startsWith('expo.modules')) continue;
  coords.set(`${group}:${artifact}:${version}`, { group, artifact, version });
}

function pomPath(group, artifact, version) {
  const dir = path.join(cache, group, artifact, version);
  if (!fs.existsSync(dir)) return null;
  for (const hash of fs.readdirSync(dir)) {
    const f = path.join(dir, hash, `${artifact}-${version}.pom`);
    if (fs.existsSync(f)) return f;
  }
  return null;
}

const tag = (xml, name) => new RegExp(`<${name}>\\s*([^<]*?)\\s*</${name}>`).exec(xml)?.[1] ?? null;
const strip = (xml) => xml.replace(/<!--[\s\S]*?-->/g, '');

/** Licences of a POM, else of its parents. */
function pomLicenses(group, artifact, version, depth = 0) {
  const file = pomPath(group, artifact, version);
  if (!file || depth > 6) return { licenses: [], url: null };
  const xml = strip(fs.readFileSync(file, 'utf8'));
  const block = /<licenses>([\s\S]*?)<\/licenses>/.exec(xml)?.[1];
  const project = xml.replace(
    /<(parent|dependencies|dependencyManagement|build|profiles|licenses|developers|distributionManagement)>[\s\S]*?<\/\1>/g,
    '',
  );
  const url = tag(/<scm>([\s\S]*?)<\/scm>/.exec(xml)?.[1] ?? '', 'url') ?? tag(project, 'url');
  if (block) {
    const licenses = [...block.matchAll(/<license>([\s\S]*?)<\/license>/g)].map((l) => ({
      name: tag(l[1], 'name'),
      url: tag(l[1], 'url'),
    }));
    if (licenses.length) return { licenses, url };
  }
  const parent = /<parent>([\s\S]*?)<\/parent>/.exec(xml)?.[1];
  if (!parent) return { licenses: [], url };
  const up = pomLicenses(tag(parent, 'groupId'), tag(parent, 'artifactId'), tag(parent, 'version'), depth + 1);
  return { licenses: up.licenses, url: url ?? up.url };
}

/** The SPDX id of a POM licence name or URL, when it is one we recognise. */
function spdx({ name, url }) {
  const s = `${name ?? ''} ${url ?? ''}`.toLowerCase();
  if (/apache|asl/.test(s) && /2\.0|2\b|license-2/.test(s)) return 'Apache-2.0';
  if (/\bmit\b|opensource\.org\/licenses\/mit/.test(s)) return 'MIT';
  if (/bsd.*3|3-clause|new bsd|bsd-3/.test(s)) return 'BSD-3-Clause';
  if (/bsd.*2|2-clause|simplified bsd/.test(s)) return 'BSD-2-Clause';
  if (/eclipse public license.*2|epl-2/.test(s)) return 'EPL-2.0';
  if (/gpl.*2.*classpath exception/.test(s)) return 'GPL-2.0-only WITH Classpath-exception-2.0';
  if (/gnu general public license.*3|gpl-3/.test(s)) return 'GPL-3.0-or-later';
  if (/android software development kit license|developer\.android\.com\/studio\/terms/.test(s)) return 'Android-SDK';
  return null;
}

const out = [];
const unknown = [];
for (const { group, artifact, version } of [...coords.values()].sort((a, b) =>
  `${a.group}:${a.artifact}`.localeCompare(`${b.group}:${b.artifact}`),
)) {
  const { licenses, url } = pomLicenses(group, artifact, version);
  const ids = licenses.map((l) => spdx(l) ?? l.name ?? l.url ?? 'UNKNOWN');
  if (!licenses.length) unknown.push(`${group}:${artifact}:${version}`);
  out.push({
    id: `${group}:${artifact}`,
    name: `${group}:${artifact}`,
    version,
    license: [...new Set(ids)].join(' OR ') || 'UNKNOWN',
    url: url ?? licenses.find((l) => l.url)?.url ?? null,
  });
}
fs.writeFileSync(outFile, JSON.stringify(out, null, 1) + '\n');
console.log(`[licenses] ${out.length} Android artifacts → ${path.relative(root, outFile)}`);
for (const u of unknown) console.warn(`[licenses] no licence in the POM of ${u}`);
